// ---- metalgtr ----------------------------------------------------------------------------------
const track3 = (() => {
  const RIFF = {"1":"X...............","2":"P-PPP-PPX...X...","3":"P-PP-PP-P-PPX..."} // a bar of sixteenths per energy: X open, P palm-muted, - choked, . held
  const gtrAt = x => {
    const c = chordAt(x), e = energy(x), r = role(x)
    if (!c || e < 1 || x >= END - 1 || r === 'outro') return null
    const pat = r === 'build' ? 'P-P-P-P-PPPPPPPP' : RIFF[Math.min(3, e)], j = floor(4 * x + 1e-9)
    let k = j
    while (pat[mod(k, 16)] === '.' && k > j - 16) k--
    const s = pat[mod(k, 16)]
    return s === '-' ? null : { at: k / 4, mute: s === 'P', c }
  }
  const powerChord = c => { const root = 40 + mod(c[2] - 40, 12); return [root, root + c[5][1], root + 12] }
  return {
  color: '#b0b0b8',
  graph: x => { const g = gtrAt(x); return g ? powerChord(g.c).map(n => -1 + (n - 40) / 14) : null },
  midi: x => { const g = gtrAt(x); return g && x - g.at < (g.mute ? 0.2 : 0.9) ? powerChord(g.c) : [] },
  formula: ["G = \\text{Cab}\\Big(\\tanh\\!\\big(2.5\\tanh(18(\\LP_{4.5\\text{к}}\\HP_{90}s + 1.2\\BP_{900}s) + 0.15)\\big) - 0.45\\BP_{500}\\Big),\\quad s = \\sum_{j}\\text{струна}(f_j)","f = (r,\\ r\\cdot 2^{5/12\\ldots 7/12},\\ 2r)\\ \\text{— квинтаккорд; P — глушение ладонью (сустейн 0.16 с); две дорожки L/R: } +9\\text{ мс},\\ +1.4\\text{ ¢}"],
  audio({ bpm }) {
    const g = metalGuitar({ seed: 131 }), fire = trigger(), verb = reverb({ room: 0.55, damp: 0.6, wet: 0.1 })
    let on = false
    return x => {
      const h = gtrAt(x)
      if (h && fire(h.at)) { g.hit(powerChord(h.c).map(n => hz(n - 60, C4)), h.mute ? 0.75 : 0.95, { mute: h.mute }); on = true }
      if (!h && on) (g.choke(0.015), (on = false))
      const [l, r] = g(), k = 0.42 * pumpAt(x)
      return verb(k * l, k * r)
    }
  },
}})()

