// ---- bass --------------------------------------------------------------------------------------
const track5 = (() => {
  const bassAt = x => {
    const c = chordAt(x), e = energy(x), r = role(x)
    if (!c || e < 1 || x >= END - 1) return null
    if (e === 1 || r === 'bridge' || r === 'outro') return { n: c[2], at: c[0], d: c[1] }
    if (e === 2) return { n: c[2], at: floor(2 * x) / 2, d: 0.45 }
    const q = mod(x, 1), at = q < 0.5 ? floor(x) : q < 0.75 ? floor(x) + 0.5 : floor(x) + 0.75
    return { n: c[2], at, d: q < 0.5 ? 0.45 : 0.22 }
  }
  return {
  color: '#5aa7ff',
  graph: x => (bassAt(x) ? -3 + (bassAt(x).n - 28) / 24 : null),
  midi: x => { const b = bassAt(x); return b && x - b.at < b.d * 0.9 ? [b.n] : [] },
  formula: ["B = 0.9\\LP_{220}s + 0.35\\LP_{1800}\\tanh(1.5s),\\quad s:\\ \\text{струна с точным строем, медиатор};\\quad \\text{галоп: } \\tfrac18 + \\tfrac1{16} + \\tfrac1{16}"],
  audio({ bpm }) {
    const b = electricBass({ bright: 0.6, seed: 7 }), fire = trigger(), lp = filter('lp'), low = filter('lp')
    let end = -1
    return x => {
      const m = bassAt(x)
      if (m && fire(m.at)) (b.hit(hz(m.n - 60, C4), 0.85 + 0.1 * hash(floor(4 * x), 31)), (end = m.at + m.d * 0.92))
      if (end > 0 && x >= end) (b.mute(0.02), (end = -1))
      const y = b() // a bass amp's two channels: the clean low end under a driven top
      return 1.4 * pumpAt(x) * (0.9 * low(y, 220) + 0.35 * lp(tanh(1.5 * y), 1800))
    }
  },
}})()

// ---- conveyor arp ------------------------------------------------------------------------------
const track6 = (() => {
  const BELT = [0,2,0,1,0,2,2,1,0,2,-1,2,0,-1,1,3] // the belt: chord tone per sixteenth (−1 = an empty slot), drawn by the seed
  const beltAt = x => {
    const c = chordAt(x), e = energy(x)
    if (!c || e < 1 || x >= END - 1 || role(x) === 'outro') return null
    const j = floor(4 * x + 1e-9), s = BELT[mod(j, 16)]
    if (s < 0 || (e === 1 && j % 2)) return null
    const v = c[3], oct = 12 + (s >= v.length ? 12 : 0)
    return { n: v[s % v.length] + oct, at: j / 4, vel: mod(j, 3) === 0 ? 0.85 : 0.55 } // accents every 3 sixteenths: 3 against 4
  }
  return {
  color: '#ffd23f',
  graph: x => (beltAt(x) && x - beltAt(x).at < 0.15 ? 0.3 + (beltAt(x).n - 55) / 40 : null),
  midi: x => (beltAt(x) && x - beltAt(x).at < 0.2 ? [beltAt(x).n] : []),
  formula: ["\\text{конвейер: } n_j = v_{B_{j \\bmod 16}},\\ B = (0,2,0,1,0,2,2,1,0,2,\\cdot,2,0,\\cdot,1,3),\\quad \\text{акцент при } j \\equiv 0 \\pmod 3 \\ (3 : 4)","Pl(f,t,v) = \\sum_k \\tfrac{v}{k} e^{-t(2.2 + 1.1k(1.3 - 0.6v))}\\sin 2\\pi kft"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = poly(pluckTone, { release: 0.05, life: 1, max: 10 }), fire = trigger(), echo = delay({ time: sec * 0.75, feedback: 0.32, wet: 0.26 }), verb = reverb({ room: 0.82, wet: 0.26 })
    return x => {
      const m = beltAt(x)
      if (m && fire(m.at)) p.hit(hz(m.n - 60, C4), m.vel, 0.12)
      return verb(...echo(...pan(0.45 * p() * pumpAt(x), 0.3)))
    }
  },
}})()

